// Common branch name constants for default branch detection.
const (
	branchMain   = "main"
	branchMaster = "master"
	// Strategy name constants
	StrategyNameManualCommit = "manual-commit"
)

// MaxCommitTraversalDepth is the safety limit for walking git commit history.
// Prevents unbounded traversal in repositories with very long histories.
const MaxCommitTraversalDepth = 1000

// errStop is a sentinel error used to break out of git log iteration.
// Shared across strategies that iterate through git commits.
// NOTE: A similar sentinel exists in checkpoint/temporary.go - this is intentional.
// Each package needs its own package-scoped sentinel for git log iteration patterns.
var errStop = errors.New("stop iteration")

// IsEmptyRepository returns true if the repository has no commits yet.
// After git-init, HEAD points to an unborn branch (e.g., refs/heads/main)
// whose target does not yet exist. repo.Head() returns ErrReferenceNotFound
// in this case.
func IsEmptyRepository(repo *git.Repository) bool {
	_, err := repo.Head()
	return errors.Is(err, plumbing.ErrReferenceNotFound)
}

// EnsureSetup ensures the strategy is properly set up.
func EnsureSetup(ctx context.Context) error {
	if err := EnsureEntireGitignore(ctx); err != nil {
		return err
	}

	// Ensure the entire/checkpoints/v1 orphan branch exists for permanent session storage
	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}
	if err := EnsureMetadataBranch(repo); err != nil {
		return fmt.Errorf("failed to ensure metadata branch: %w", err)
	}

	// Install generic hooks (they delegate to strategy at runtime)
	if !IsGitHookInstalled(ctx) {
		localDev, absoluteHookPath := hookSettingsFromConfig(ctx)
		if _, err := InstallGitHook(ctx, true, localDev, absoluteHookPath); err != nil {
			return fmt.Errorf("failed to install git hooks: %w", err)
		}
	}
	return nil
}

// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
// Returns true if target can reach commit by following parent links.
// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
func IsAncestorOf(ctx context.Context, repo *git.Repository, commit, target plumbing.Hash) bool {
	if commit == target {
		return true
	}

	iter, err := repo.Log(&git.LogOptions{From: target})
	if err != nil {
		return false
	}
	defer iter.Close()

	found := false
	count := 0
	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
		if err := ctx.Err(); err != nil {
			return err //nolint:wrapcheck // Propagating context cancellation
		}
		count++
		if count > MaxCommitTraversalDepth {
			return errStop
		}
		if c.Hash == commit {
			found = true
			return errStop
		}
		return nil
	})

	return found
}

// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Warn (once per process) if metadata branches are disconnected
	WarnIfMetadataDisconnected()

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		//nolint:nilerr // No sessions branch yet is expected, return empty list
		return []CheckpointInfo{}, nil
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	var checkpoints []CheckpointInfo

	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
	// The tree has 2-character directories (hex buckets)
	for _, bucketEntry := range tree.Entries {
		if bucketEntry.Mode != filemode.Dir {
			continue
		}
		// Bucket should be 2 hex chars
		if len(bucketEntry.Name) != 2 {
			continue
		}

		)
		return ""
	}
	url, err := deriveCheckpointURL(pushRemoteURL, config)
	if err != nil {
		logging.Debug(ctx, "checkpoint-remote: could not derive v2 checkpoint URL",
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ""
	}
	return url
}

// ResolveRemoteRepo returns the host, owner, and repo name for the given git remote.
// It parses the remote URL (SSH or HTTPS) and extracts the components.
// For example, git@github.com:org/my-repo.git returns ("github.com", "org", "my-repo").
func ResolveRemoteRepo(ctx context.Context, remoteName string) (host, owner, repo string, err error) {
	rawURL, err := getRemoteURL(ctx, remoteName)
	if err != nil {
		return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
	}
	info, err := parseGitRemoteURL(rawURL)
	if err != nil {
		return "", "", "", fmt.Errorf("parse remote URL: %w", err)
	}
	return info.host, info.owner, info.repo, nil
}

// gitRemoteInfo holds parsed components of a git remote URL.
type gitRemoteInfo struct {
	protocol string // "ssh" or "https"
	host     string // e.g., "github.com"
	owner    string // e.g., "org"
	repo     string // e.g., "my-repo" (without .git)
}

// parseGitRemoteURL parses a git remote URL into its components.
// Supports:
//   - SSH SCP format: git@github.com:org/repo.git
//   - HTTPS format: https://github.com/org/repo.git
//   - SSH protocol format: ssh://git@github.com/org/repo.git
func parseGitRemoteURL(rawURL string) (*gitRemoteInfo, error) {
	rawURL = strings.TrimSpace(rawURL)

	// SSH SCP format: git@github.com:org/repo.git
	if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
		// Split on the first ":"
		parts := strings.SplitN(rawURL, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid SSH URL: %s", redactURL(rawURL))
		}
		hostPart := parts[0] // e.g., "git@github.com"
		pathPart := parts[1] // e.g., "org/repo.git"

		host := hostPart
		if idx := strings.Index(host, "@"); idx >= 0 {
			host = host[idx+1:]
		}

		owner, repo, err := splitOwnerRepo(pathPart)
		if err != nil {
			return nil, err
		}

		return &gitRemoteInfo{protocol: protocolSSH, host: host, owner: owner, repo: repo}, nil
	}

	// URL format: https://github.com/org/repo.git or ssh://git@github.com/org/repo.git
	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %s", redactURL(rawURL))
	}

	protocol := u.Scheme
	if protocol == "" {
		return nil, fmt.Errorf("no protocol in URL: %s", redactURL(rawURL))
	}
	host := u.Hostname()

	// Path is like /org/repo.git — trim leading slash
	pathPart := strings.TrimPrefix(u.Path, "/")
	owner, repo, err := splitOwnerRepo(pathPart)
	if err != nil {
		return nil, err
	}

	return &gitRemoteInfo{protocol: protocol, host: host, owner: owner, repo: repo}, nil
}

// splitOwnerRepo splits "org/repo.git" into owner and repo (without .git suffix).
func splitOwnerRepo(path string) (string, string, error) {
	path = strings.TrimSuffix(path, ".git")
	parts := strings.SplitN(path, "/", 2)
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
	}
	return parts[0], parts[1], nil
}

