+func normalizeGitConfigForGuard(content string) string {
+	lines := strings.Split(content, "\n")
+	var normalized []string
+
+	for i := 0; i < len(lines); {
+		line := lines[i]
+		if !strings.HasPrefix(line, "[remote ") {
+			normalized = append(normalized, line)
+			i++
+			continue
+		}
+
+		section := []string{line}
+		j := i + 1
+		for ; j < len(lines); j++ {
+			if strings.HasPrefix(lines[j], "[") {
+				break
+			}
+			section = append(section, lines[j])
+		}
+
+		if shouldIgnoreGitConfigSection(section) {
+			i = j
+			continue
+		}
+
+		normalized = append(normalized, section...)
+		i = j
+	}
+
+	return strings.Join(normalized, "\n")
+}
+
+func shouldIgnoreGitConfigSection(section []string) bool {
+	if len(section) == 0 {
